create table if not exists public.businesses (id uuid primary key default gen_random_uuid(), user_id uuid, business_name text not null, category text, phone text, email text, website text, address text, city text, state text, country text, google_maps_url text, rating numeric, review_count integer, latitude numeric, longitude numeric, instagram text, facebook text, linkedin text, youtube text, source text default 'google_maps', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.searches (id uuid primary key default gen_random_uuid(), user_id uuid, keyword text, location text, total_results integer default 0, created_at timestamptz not null default now());
create table if not exists public.leads (id uuid primary key default gen_random_uuid(), user_id uuid, business_id uuid references public.businesses(id) on delete cascade, lead_score integer, lead_status text default 'new', notes text, created_at timestamptz not null default now());
